package uk.ac.ravensbourne.casevault.web;
import java.nio.charset.StandardCharsets; import java.util.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import uk.ac.ravensbourne.casevault.report.ReportService; import uk.ac.ravensbourne.casevault.security.UserPrincipal;
@RestController @RequestMapping("/cases/{caseId}/reports") public class ReportController { private final ReportService reports; public ReportController(ReportService r){reports=r;} @PostMapping @PreAuthorize("hasRole('SECURITY_ANALYST')") public ResponseEntity<Void> generate(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID caseId){var r=reports.generate(p,caseId);return ResponseEntity.created(java.net.URI.create("/cases/"+caseId+"/reports/"+r.getId())).build();} @GetMapping("/{id}") @PreAuthorize("isAuthenticated()") public ResponseEntity<byte[]> download(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID caseId,@PathVariable UUID id){var r=reports.approvedForClient(p,caseId,id);return ResponseEntity.ok().contentType(MediaType.TEXT_PLAIN).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=case-report-"+r.getVersion()+".txt").cacheControl(CacheControl.noStore()).body(r.getContent().getBytes(StandardCharsets.UTF_8));} }
